import socketioClient from '../modified/index';
import eventToPromise from 'event-to-promise';

suite('binary connections', () => {

  let server;
  setup(async () => {
    let http = require('http').createServer();
    let io = require('socket.io')(http, {
      // XXX: Only accept websocket clients for now to work around app issues.
      transports: ['websocket']
    });

    // Install the socket.io listeners.
    http.listen(0);
    let errorEvent = eventToPromise(http, 'error').then(err => {
      throw err;
    });

    let connected = eventToPromise(http, 'listening');

    // await to be connected correctly...
    await Promise.race([errorEvent, eventToPromise(http, 'listening')]);

    // This interface is only ever supposed to be used from tests.
    server = {
      io,
      url: `http://localhost:${http.address().port}`,
      close: async() => {
        http.close();
      }
    };
  });

  teardown(async () => {
    await server.close()
  });

  function send(client, ...args) {
    return new Promise((accept) => {
      args.push(accept);
      client.emit(...args);
    });
  }

  test('chat with strings...', async () => {

    server.io.on('connection', (socket) => {
      console.log('got socket');
      socket.on('string', (msg, ack) => {
        console.log(msg);
        ack();
      });
    });

    let client = socketioClient(server.url, {
      transports: ['websocket']
    });
    client.on('error', (err) => console.log(err.stack));
    await eventToPromise(client, 'connect');

    await send(client, 'string', new Buffer('string'));
  });

});
